import com.cowave.search.domain.index.enums.Operation
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe
import io.mockk.coEvery
import io.mockk.coVerify
import io.mockk.mockk
import io.mockk.slot
import org.springframework.http.HttpMethod

class LegacySyncRepositoryImplTest :
    FunSpec({

        val legacyApiClient = mockk<LegacyApiClient>()
        val repository = LegacyReserveSyncRepositoryImpl(legacyApiClient)

        beforeEach {
            coEvery { legacyApiClient.pushQueue(any(), any(), any()) } returns Unit
        }

        context("pushLinkedProducts") {
            val products =
                listOf(
                    LinkedProductRequest(shopProductCode = "P001", shopCode = "S001"),
                )

            test("CREATE 연동상품 동기화 - POST로 호출한다") {
                val serviceSlot = slot<String>()
                val methodSlot = slot<HttpMethod>()

                coEvery {
                    legacyApiClient.pushQueue(capture(serviceSlot), capture(methodSlot), any())
                } returns Unit

                repository.pushLinkedProducts(products, Operation.CREATE)

                serviceSlot.captured shouldBe "PDM"
                methodSlot.captured shouldBe HttpMethod.POST
                coVerify(exactly = 1) { legacyApiClient.pushQueue("PDM", HttpMethod.POST, products) }
            }

            test("UPDATE 연동상품 동기화 - PUT으로 호출한다") {
                val methodSlot = slot<HttpMethod>()

                coEvery {
                    legacyApiClient.pushQueue(any(), capture(methodSlot), any())
                } returns Unit

                repository.pushLinkedProducts(products, Operation.UPDATE)

                methodSlot.captured shouldBe HttpMethod.PUT
                coVerify(exactly = 1) { legacyApiClient.pushQueue("PDM", HttpMethod.PUT, products) }
            }

            test("DELETE 연동상품 동기화 - DELETE로 호출한다") {
                val methodSlot = slot<HttpMethod>()

                coEvery {
                    legacyApiClient.pushQueue(any(), capture(methodSlot), any())
                } returns Unit

                repository.pushLinkedProducts(products, Operation.DELETE)

                methodSlot.captured shouldBe HttpMethod.DELETE
                coVerify(exactly = 1) { legacyApiClient.pushQueue("PDM", HttpMethod.DELETE, products) }
            }
        }

        context("pushUnlinkedProducts") {
            // TODO(human): 비연동상품 테스트 데이터와 3가지 Operation 테스트 케이스를 구현하세요
        }

        context("pushUnlinkedProductDeletes") {
            val products =
                listOf(
                    UnlinkedProductDeleteRequest(shopCode = "S001", shopProductCode = "P001"),
                )

            test("비연동상품 삭제 동기화 - DELETE로 호출한다") {
                val serviceSlot = slot<String>()
                val methodSlot = slot<HttpMethod>()

                coEvery {
                    legacyApiClient.pushQueue(capture(serviceSlot), capture(methodSlot), any())
                } returns Unit

                repository.pushUnlinkedProductDeletes(products)

                serviceSlot.captured shouldBe "TCMPNY_LINK"
                methodSlot.captured shouldBe HttpMethod.DELETE
                coVerify(exactly = 1) {
                    legacyApiClient.pushQueue("TCMPNY_LINK", HttpMethod.DELETE, products)
                }
            }
        }
    })

